def contrast(acc, groups):
    g = groups['x']
    a = acc['x']
    return a[g == 'ctrl'].mean() - a[g == 'foil'].mean()

def contrast(acc, groups):
    a = acc['x']
    g = groups['x']
    return a[g == 'massed'].mean() - a[g == 'spaced'].mean()

def contrast(acc, groups):
    g = groups['x']
    a = acc['x']
    return a[g == 'U'].mean() - a[g == 'S'].mean()
